<?php
if(!defined('ABSPATH'))exit;
function legacyx_register_communication_types(){register_post_type('legacyx_appointment',array('labels'=>array('name'=>'Appointments','singular_name'=>'Appointment','add_new_item'=>'Schedule Appointment'),'public'=>false,'show_ui'=>true,'show_in_menu'=>true,'menu_icon'=>'dashicons-calendar-alt','supports'=>array('title'),'show_in_rest'=>false,'capability_type'=>'post','map_meta_cap'=>true));register_post_type('legacyx_message',array('labels'=>array('name'=>'Client Messages','singular_name'=>'Client Message','add_new_item'=>'New Client Message'),'public'=>false,'show_ui'=>true,'show_in_menu'=>true,'menu_icon'=>'dashicons-email-alt','supports'=>array('title'),'show_in_rest'=>false,'capability_type'=>'post','map_meta_cap'=>true));}add_action('init','legacyx_register_communication_types');
function legacyx_comm_client_select($post){$client_id=absint(get_post_meta($post->ID,'_legacyx_client_id',true));$clients=get_posts(array('post_type'=>'legacyx_client','post_status'=>'any','numberposts'=>-1,'orderby'=>'title','order'=>'ASC'));echo '<p><label><strong>Universal Client Profile</strong></label><br><select name="legacyx_client_id" style="width:100%"><option value="">Select client</option>';foreach($clients as $c){$code=get_post_meta($c->ID,'_legacyx_client_id',true);echo '<option value="'.esc_attr($c->ID).'" '.selected($client_id,$c->ID,false).'>'.esc_html($c->post_title.' · '.$code).'</option>';}echo '</select></p>';}
function legacyx_comm_boxes(){add_meta_box('legacyx_appointment_details','Appointment Details','legacyx_render_appointment_box','legacyx_appointment','normal','high');add_meta_box('legacyx_message_details','Message Details','legacyx_render_message_box','legacyx_message','normal','high');}add_action('add_meta_boxes','legacyx_comm_boxes');
function legacyx_render_appointment_box($post){wp_nonce_field('legacyx_save_appointment','legacyx_appointment_nonce');legacyx_comm_client_select($post);$fields=array('appointment_status'=>'Status','appointment_type'=>'Meeting Type','appointment_date'=>'Date','appointment_time'=>'Time','advisor'=>'Advisor / Host','meeting_location'=>'Location / Meeting Link','agenda'=>'Agenda / Purpose','client_note'=>'Client-visible Note','staff_note'=>'Internal Staff Note');foreach($fields as $k=>$l){$v=get_post_meta($post->ID,'_legacyx_'.$k,true);if(in_array($k,array('agenda','client_note','staff_note'),true))echo '<p><label><strong>'.esc_html($l).'</strong></label><br><textarea name="legacyx_'.$k.'" style="width:100%;min-height:80px">'.esc_textarea($v).'</textarea></p>';elseif($k==='appointment_status'){echo '<p><label><strong>Status</strong></label><br><select name="legacyx_appointment_status" style="width:100%">';foreach(array('Requested','Scheduled','Confirmed','Completed','Cancelled','No Show','Reschedule Requested') as $o)echo '<option '.selected($v,$o,false).'>'.esc_html($o).'</option>';echo '</select></p>';}else{$type=$k==='appointment_date'?'date':($k==='appointment_time'?'time':'text');echo '<p><label><strong>'.esc_html($l).'</strong></label><br><input type="'.$type.'" name="legacyx_'.$k.'" value="'.esc_attr($v).'" style="width:100%"></p>';}}}
function legacyx_render_message_box($post){wp_nonce_field('legacyx_save_message','legacyx_message_nonce');legacyx_comm_client_select($post);$direction=get_post_meta($post->ID,'_legacyx_direction',true);$status=get_post_meta($post->ID,'_legacyx_message_status',true);echo '<p><label><strong>Direction</strong></label><br><select name="legacyx_direction" style="width:100%">';foreach(array('Staff to Client','Client to Staff') as $o)echo '<option '.selected($direction,$o,false).'>'.esc_html($o).'</option>';echo '</select></p><p><label><strong>Status</strong></label><br><select name="legacyx_message_status" style="width:100%">';foreach(array('New','Open','Replied','Resolved','Archived') as $o)echo '<option '.selected($status,$o,false).'>'.esc_html($o).'</option>';echo '</select></p>';foreach(array('message_body'=>'Message','staff_note'=>'Internal Staff Note') as $k=>$l){$v=get_post_meta($post->ID,'_legacyx_'.$k,true);echo '<p><label><strong>'.esc_html($l).'</strong></label><br><textarea name="legacyx_'.$k.'" style="width:100%;min-height:110px">'.esc_textarea($v).'</textarea></p>';}}
function legacyx_save_appointment($id){if(!isset($_POST['legacyx_appointment_nonce'])||!wp_verify_nonce(sanitize_text_field(wp_unslash($_POST['legacyx_appointment_nonce'])),'legacyx_save_appointment')||!current_user_can('edit_post',$id))return;update_post_meta($id,'_legacyx_client_id',absint($_POST['legacyx_client_id']??0));foreach(array('appointment_status','appointment_type','appointment_date','appointment_time','advisor','meeting_location') as $k)update_post_meta($id,'_legacyx_'.$k,sanitize_text_field(wp_unslash($_POST['legacyx_'.$k]??'')));foreach(array('agenda','client_note','staff_note') as $k)update_post_meta($id,'_legacyx_'.$k,sanitize_textarea_field(wp_unslash($_POST['legacyx_'.$k]??'')));}add_action('save_post_legacyx_appointment','legacyx_save_appointment');
function legacyx_save_message($id){if(!isset($_POST['legacyx_message_nonce'])||!wp_verify_nonce(sanitize_text_field(wp_unslash($_POST['legacyx_message_nonce'])),'legacyx_save_message')||!current_user_can('edit_post',$id))return;update_post_meta($id,'_legacyx_client_id',absint($_POST['legacyx_client_id']??0));foreach(array('direction','message_status') as $k)update_post_meta($id,'_legacyx_'.$k,sanitize_text_field(wp_unslash($_POST['legacyx_'.$k]??'')));foreach(array('message_body','staff_note') as $k)update_post_meta($id,'_legacyx_'.$k,sanitize_textarea_field(wp_unslash($_POST['legacyx_'.$k]??'')));}add_action('save_post_legacyx_message','legacyx_save_message');
function legacyx_get_client_appointments($client_id){return get_posts(array('post_type'=>'legacyx_appointment','post_status'=>'any','numberposts'=>20,'meta_key'=>'_legacyx_client_id','meta_value'=>absint($client_id),'orderby'=>'date','order'=>'DESC'));}
function legacyx_get_client_messages($client_id){return get_posts(array('post_type'=>'legacyx_message','post_status'=>'any','numberposts'=>30,'meta_key'=>'_legacyx_client_id','meta_value'=>absint($client_id),'orderby'=>'date','order'=>'DESC'));}
function legacyx_communication_counts($client_id){$a=legacyx_get_client_appointments($client_id);$m=legacyx_get_client_messages($client_id);$out=array('appointments'=>count($a),'upcoming'=>0,'messages'=>count($m),'open_messages'=>0);$today=current_time('Y-m-d');foreach($a as $r){$d=get_post_meta($r->ID,'_legacyx_appointment_date',true);$s=get_post_meta($r->ID,'_legacyx_appointment_status',true);if($d>=$today&&!in_array($s,array('Completed','Cancelled','No Show'),true))$out['upcoming']++;}foreach($m as $r){$s=get_post_meta($r->ID,'_legacyx_message_status',true);if(in_array($s,array('New','Open','Replied'),true))$out['open_messages']++;}return $out;}
